frappe.ui.form.on("Interview", {
    refresh(frm) {
        toggle_hr_section(frm);
    },

    interview_type(frm) {
        toggle_hr_section(frm);
    }
});

function toggle_hr_section(frm) {

    // HR Screening select hai ya nahi
    const show_hr = frm.doc.interview_type === "HR Screening";

    // Pura section show/hide
    frm.set_df_property(
        "custom_hr_screening",
        "hidden",
        !show_hr
    );

    // Section ke andar ki fields bhi show/hide
    const hr_fields = [
        "custom_notice_period_match",
        "custom_salary_bracket_match",
        "custom_fit_for_calco_culture"
        // future fields yahan add kar sakte ho
        // "custom_communication_english",
        // "custom_communication_hindi",
        // "custom_overall_recommendation",
        // "custom_hr_remarks"
    ];

    hr_fields.forEach(field => {
        frm.set_df_property(field, "hidden", !show_hr);
    });

    frm.refresh_fields();
}

frappe.ui.form.on("Leave Application", {
    before_save: function(frm) {

        // Sirf NEW Leave Application par validation
        if (!frm.is_new()) {
            return;
        }

        const today = frappe.datetime.get_today();

        // Agar date past hai
        if (
            frm.doc.from_date &&
            frm.doc.from_date < today
        ) {

            // Administrator ko kisi bhi Leave Type ki backdate allowed
            if (frappe.session.user === "Administrator") {
                return;
            }

            // Non-Administrator ke liye allowed backdated Leave Types
            const allowedBackDate = [
                "Sick Leave",
                "Mispunch",
                "On Duty",
                "Short Leave",
                "Privilege Leave"
            ];

            // Allowed type nahi hai to block
            if (!allowedBackDate.includes(frm.doc.leave_type)) {
                frappe.throw(
                    __("Past dated leave is allowed only for Sick Leave, Mispunch, On Duty, Short Leave, and Privilege Leave.")
                );
            }
        }
    }
});

// ============================================================
// GET COMPONENT CATEGORY FIELDNAME
// ============================================================

function get_category_fieldname(frm) {

    var meta = frappe.get_meta("Job Offer Salary Component");

    var field = meta.fields.find(function(df) {

        return df.label === "Component Category";

    });

    return field ? field.fieldname : null;
}


// ============================================================
// COMPONENTS TO EXCLUDE FROM JOB OFFER
// ============================================================

var excluded_salary_components = [

    "Overtime",
    "Shift Allowance",
    "Leave Encashment",
    "Arrear"

];


// ============================================================
// CATEGORY SORT ORDER
// ============================================================

var salary_category_order = {

    "Earning": 1,

    "Employee Deduction": 2,

    "Employer Contribution": 3,

    "Annual Benefit": 4

};


// ============================================================
// SALARY COMPONENT FIXED SORT ORDER
// ============================================================
//
// EARNING
//
// 1. Basic
// 2. House Rent Allowance
// 3. Conveyance Allowance
// 4. Uniform Allowance
// 5. Children Education Allowance
// 6. Medical Allowance
// 7. Entertainment Allowance
// 8. Special Allowance
//
// EMPLOYEE DEDUCTION
//
// 1. Provident Fund
// 2. ESI
// 3. Labour Welfare Fund
// 4. Cantten-Employee
//
// EMPLOYER CONTRIBUTION
//
// 1. Provident Fund - Employer
// 2. ESI -Employer
// 3. Labour Welfare Fund - Employer
// 4. Cantten-Employer
//
// ANNUAL BENEFIT
//
// Fixed order nahi hai.
// Alphabetical order mein aayega.
//
// ============================================================

var salary_component_order = {

    // ========================================================
    // EARNING
    // ========================================================

    "Earning": {

        "Basic": 1,

        "House Rent Allowance": 2,

        "Conveyance Allowance": 3,

        "Uniform Allowance": 4,

        "Children Education Allowance": 5,

        "Medical Allowance": 6,

        "Entertainment Allowance": 7,

        "Special Allowance": 8

    },


    // ========================================================
    // EMPLOYEE DEDUCTION
    // ========================================================

    "Employee Deduction": {

        "Provident Fund": 1,

        "ESI": 2,

        "Labour Welfare Fund": 3,

        "Cantten-Employee": 4

    },


    // ========================================================
    // EMPLOYER CONTRIBUTION
    // ========================================================

    "Employer Contribution": {

        "Provident Fund - Employer": 1,

        "ESI -Employer": 2,

        "Labour Welfare Fund - Employer": 3,

        "Cantten-Employer": 4

    }

};


// ============================================================
// SORT SALARY COMPONENTS
// ============================================================
//
// 1. Category ke according sort
//
// 2. Category ke andar fixed component order
//
// 3. Jo component fixed list mein nahi hai,
//    woh alphabetical order mein
//
// ============================================================

function sort_salary_components(frm) {

    var category_fieldname =
        get_category_fieldname(frm);


    if (!category_fieldname) {

        console.error(
            "Component Category field not found"
        );

        return;

    }


    var rows =
        frm.doc.custom_job_offer_salary_component || [];


    // ========================================================
    // SORT
    // ========================================================

    rows.sort(function(a, b) {

        var categoryA =
            a[category_fieldname] || "";

        var categoryB =
            b[category_fieldname] || "";


        // ====================================================
        // CATEGORY ORDER
        // ====================================================

        var orderA =
            salary_category_order[categoryA] || 99;

        var orderB =
            salary_category_order[categoryB] || 99;


        // Different category
        if (orderA !== orderB) {

            return orderA - orderB;

        }


        // ====================================================
        // COMPONENT NAME
        // ====================================================

        var componentA =
            a.salary_component || "";

        var componentB =
            b.salary_component || "";


        // ====================================================
        // FIXED COMPONENT ORDER
        // ====================================================

        var componentOrderA = 999;

        var componentOrderB = 999;


        // ----------------------------------------------------
        // COMPONENT A
        // ----------------------------------------------------

        if (
            salary_component_order[categoryA] &&
            salary_component_order[categoryA][componentA] !== undefined
        ) {

            componentOrderA =
                salary_component_order[categoryA][componentA];

        }


        // ----------------------------------------------------
        // COMPONENT B
        // ----------------------------------------------------

        if (
            salary_component_order[categoryB] &&
            salary_component_order[categoryB][componentB] !== undefined
        ) {

            componentOrderB =
                salary_component_order[categoryB][componentB];

        }


        // ====================================================
        // FIXED ORDER
        // ====================================================

        if (componentOrderA !== componentOrderB) {

            return componentOrderA - componentOrderB;

        }


        // ====================================================
        // ALPHABETICAL
        // ====================================================

        return componentA.localeCompare(
            componentB,
            undefined,
            {
                sensitivity: "base"
            }
        );

    });


    // ========================================================
    // RESET CHILD TABLE INDEX
    // ========================================================

    rows.forEach(function(row, index) {

        row.idx = index + 1;

    });


    // ========================================================
    // REFRESH TABLE
    // ========================================================

    frm.refresh_field(
        "custom_job_offer_salary_component"
    );

}


// ============================================================
// CALCULATE JOB OFFER SALARY
// ============================================================
//
// FINAL FORMULAS:
//
// 1. Monthly CTC
//    = Earning
//    + Annual Benefit
//    + Employer Contribution
//
// 2. Monthly Gross Salary
//    = Earning ONLY
//
// 3. Monthly Net In Hand
//    = Monthly Gross Salary
//    - Employee Deduction
//
// 4. Annual CTC
//    = Monthly CTC × 12
//
// 5. Annual Amount
//    = Monthly Amount × 12
//
// ============================================================

function calculate_job_offer_salary(frm) {

    // ========================================================
    // ONLY CALCULATE IN DRAFT
    // ========================================================

    if (frm.doc.docstatus != 0) {

        return;

    }


    // ========================================================
    // GET CATEGORY FIELDNAME
    // ========================================================

    var category_fieldname =
        get_category_fieldname(frm);


    if (!category_fieldname) {

        console.error(
            "Component Category field not found"
        );

        return;

    }


    // ========================================================
    // TOTALS
    // ========================================================

    var earning_monthly = 0;

    var employee_deduction_monthly = 0;

    var employer_contribution_monthly = 0;

    var annual_benefit_monthly = 0;


    // ========================================================
    // LOOP THROUGH CHILD TABLE
    // ========================================================

    (
        frm.doc.custom_job_offer_salary_component || []
    ).forEach(function(row) {

        var category =
            row[category_fieldname] || "";

        var monthly =
            flt(row.amount_monthly);


        // ====================================================
        // EARNING
        // ====================================================

        if (category === "Earning") {

            earning_monthly += monthly;

        }


        // ====================================================
        // EMPLOYEE DEDUCTION
        // ====================================================

        else if (
            category === "Employee Deduction"
        ) {

            employee_deduction_monthly += monthly;

        }


        // ====================================================
        // EMPLOYER CONTRIBUTION
        // ====================================================

        else if (
            category === "Employer Contribution"
        ) {

            employer_contribution_monthly += monthly;

        }


        // ====================================================
        // ANNUAL BENEFIT
        // ====================================================

        else if (
            category === "Annual Benefit"
        ) {

            annual_benefit_monthly += monthly;

        }

    });


    // ========================================================
    // MONTHLY CTC
    // ========================================================
    //
    // EARNING
    // + ANNUAL BENEFIT
    // + EMPLOYER CONTRIBUTION
    //
    // Employee Deduction NOT included
    // ========================================================

    var monthly_ctc =
        earning_monthly +
        annual_benefit_monthly +
        employer_contribution_monthly;


    // ========================================================
    // MONTHLY GROSS SALARY
    // ========================================================
    //
    // EARNING ONLY
    //
    // Annual Benefit NOT included
    // Employer Contribution NOT included
    // ========================================================

    var monthly_gross_salary =
        earning_monthly;


    // ========================================================
    // MONTHLY NET IN HAND
    // ========================================================
    //
    // GROSS
    // - EMPLOYEE DEDUCTION
    // ========================================================

    var monthly_net_in_hand =
        monthly_gross_salary -
        employee_deduction_monthly;


    // ========================================================
    // ANNUAL CTC
    // ========================================================

    var annual_ctc =
        monthly_ctc * 12;


    // ========================================================
    // UPDATE MONTHLY GROSS SALARY
    // ========================================================

    frm.set_value(
        "custom_monthly_gross_salary",
        monthly_gross_salary
    );


    // ========================================================
    // UPDATE MONTHLY NET IN HAND
    // ========================================================

    frm.set_value(
        "custom_monthly_net_in_hand",
        monthly_net_in_hand
    );


    // ========================================================
    // UPDATE MONTHLY CTC
    // ========================================================

    frm.set_value(
        "custom_monthly_ctc_",
        monthly_ctc
    );


    // ========================================================
    // UPDATE ANNUAL CTC
    // ========================================================

    frm.set_value(
        "custom_annual_ctc_",
        annual_ctc
    );

}


// ============================================================
// SET CATEGORY FOR ONE CHILD ROW
// ============================================================
//
// Salary Component master:
// custom_component_category
//
// ============================================================

function set_salary_component_category(frm, row) {

    if (!row.salary_component) {

        return;

    }


    // ========================================================
    // GET CATEGORY FIELDNAME
    // ========================================================

    var category_fieldname =
        get_category_fieldname(frm);


    if (!category_fieldname) {

        console.error(
            "Component Category field not found"
        );

        return;

    }


    // ========================================================
    // GET CATEGORY FROM SALARY COMPONENT
    // ========================================================

    frappe.db.get_value(
        "Salary Component",
        row.salary_component,
        "custom_component_category"
    ).then(function(r) {

        var category = "";


        if (
            r &&
            r.message &&
            r.message.custom_component_category
        ) {

            category =
                r.message.custom_component_category;

        }


        // ====================================================
        // SET CATEGORY
        // ====================================================

        frappe.model.set_value(
            row.doctype,
            row.name,
            category_fieldname,
            category
        ).then(function() {


            // =================================================
            // SORT
            // =================================================

            sort_salary_components(frm);


            // =================================================
            // CALCULATE
            // =================================================

            calculate_job_offer_salary(frm);

        });

    });

}


// ============================================================
// LOAD SALARY COMPONENTS
// ============================================================

function load_salary_components(frm) {

    frappe.call({

        method: "frappe.client.get_list",

        args: {

            doctype: "Salary Component",

            fields: [
                "name"
            ],

            order_by: "name asc",

            limit_page_length: 100

        },

        callback: function(r) {

            if (
                !r ||
                !r.message
            ) {

                return;

            }


            // =================================================
            // GET CATEGORY FIELDNAME
            // =================================================

            var category_fieldname =
                get_category_fieldname(frm);


            if (!category_fieldname) {

                frappe.msgprint(
                    "Component Category field not found in Job Offer Salary Component"
                );

                return;

            }


            // =================================================
            // EXISTING COMPONENTS
            // =================================================

            var existing = {};


            (
                frm.doc.custom_job_offer_salary_component || []
            ).forEach(function(row) {

                if (row.salary_component) {

                    existing[
                        row.salary_component
                    ] = true;

                }

            });


            // =================================================
            // ADD MISSING SALARY COMPONENTS
            // =================================================

            r.message.forEach(function(d) {


                // =================================================
                // EXCLUDE COMPONENT
                // =================================================

                if (
                    excluded_salary_components.indexOf(
                        d.name
                    ) !== -1
                ) {

                    return;

                }


                // =================================================
                // ADD IF NOT EXISTS
                // =================================================

                if (!existing[d.name]) {

                    var row =
                        frm.add_child(
                            "custom_job_offer_salary_component"
                        );


                    // ---------------------------------------------
                    // SALARY COMPONENT
                    // ---------------------------------------------

                    row.salary_component =
                        d.name;


                    // ---------------------------------------------
                    // MONTHLY AMOUNT
                    // ---------------------------------------------

                    row.amount_monthly = 0;


                    // ---------------------------------------------
                    // ANNUAL AMOUNT
                    // ---------------------------------------------

                    row.amount_annual = 0;


                    // ---------------------------------------------
                    // GET CATEGORY
                    // ---------------------------------------------

                    set_salary_component_category(
                        frm,
                        row
                    );

                }

            });


            // =================================================
            // UPDATE CATEGORY OF EXISTING ROWS
            // =================================================

            (
                frm.doc.custom_job_offer_salary_component || []
            ).forEach(function(row) {

                if (row.salary_component) {

                    set_salary_component_category(
                        frm,
                        row
                    );

                }

            });


            // =================================================
            // REFRESH CHILD TABLE
            // =================================================

            frm.refresh_field(
                "custom_job_offer_salary_component"
            );


            // =================================================
            // SORT
            // =================================================

            sort_salary_components(frm);


            // =================================================
            // CALCULATE
            // =================================================

            calculate_job_offer_salary(frm);

        }

    });

}


// ============================================================
// JOB OFFER FORM EVENTS
// ============================================================

frappe.ui.form.on(
    "Job Offer",
    {

        // ====================================================
        // ONLOAD
        // ====================================================

        onload: function(frm) {

            load_salary_components(frm);

        },


        // ====================================================
        // REFRESH
        // ====================================================

        refresh: function(frm) {

            sort_salary_components(frm);

            calculate_job_offer_salary(frm);

        }

    }
);


// ============================================================
// CHILD TABLE EVENTS
// ============================================================

frappe.ui.form.on(
    "Job Offer Salary Component",
    {

        // ====================================================
        // MONTHLY AMOUNT
        // ====================================================

        amount_monthly: function(frm, cdt, cdn) {

            var row =
                locals[cdt][cdn];


            // =================================================
            // ANNUAL AMOUNT
            // =================================================
            //
            // Annual = Monthly × 12
            //
            // =================================================

            frappe.model.set_value(
                cdt,
                cdn,
                "amount_annual",
                flt(row.amount_monthly) * 12
            );


            // =================================================
            // RECALCULATE
            // =================================================

            calculate_job_offer_salary(frm);

        },


        // ====================================================
        // ANNUAL AMOUNT
        // ====================================================

        amount_annual: function(frm, cdt, cdn) {

            calculate_job_offer_salary(frm);

        },


        // ====================================================
        // SALARY COMPONENT CHANGE
        // ====================================================

        salary_component: function(frm, cdt, cdn) {

            var row =
                locals[cdt][cdn];


            // =================================================
            // COMPONENT CLEARED
            // =================================================

            if (!row.salary_component) {

                var category_fieldname =
                    get_category_fieldname(frm);


                if (category_fieldname) {

                    frappe.model.set_value(
                        cdt,
                        cdn,
                        category_fieldname,
                        ""
                    );

                }


                // ---------------------------------------------
                // SORT
                // ---------------------------------------------

                sort_salary_components(frm);


                // ---------------------------------------------
                // CALCULATE
                // ---------------------------------------------

                calculate_job_offer_salary(frm);

                return;

            }


            // =================================================
            // SET CATEGORY
            // =================================================

            set_salary_component_category(
                frm,
                row
            );

        }

    }
);

