/* =========================================================
   OFFER LETTER PRINT FORMAT - CSS (wkhtmltopdf SAFE VERSION)
   ---------------------------------------------------------
   NOTE: ERPNext PDF/Print wkhtmltopdf engine use karta hai,
   jo CSS variables (--variable / var()) support nahi karta.
   Isliye is file me sabhi sizes DIRECTLY likhi gayi hain.

   SIZE CHANGE KARNE KE LIYE:
   Neeche jahan bhi "font-size: 12px;" jaisi line dikhe,
   sirf wahi number (12px) change karein us section ke liye.
   Sabse jyada use hone wale 2 values yeh hain:
     - 12px  -> normal paragraph/body text
     - 14px  -> section headings (h4)
   ========================================================= */

/* ---------- 1. GENERAL BODY TEXT ---------- */
body, p, li, td, th {
    font-size: 12px;
    line-height: 1.6;
    font-family: Arial, Helvetica, sans-serif;
}

/* ---------- 2. SECTION HEADINGS (1. EFFECTIVE DATE, etc.) ---------- */
h4 {
    font-size: 14px;
    font-weight: bold;
    margin-top: 10px;
    margin-bottom: 6px;
}

/* ---------- 3. TITLE (Acknowledgement & Acceptance) ---------- */
h3 {
    font-size: 16px;
    font-weight: bold;
}

/* ---------- 4. NOTES / SECTION WRAPPER ---------- */
.notes {
    font-size: 12px;
    margin-bottom: 10px;
}

.notes p {
    font-size: 12px;
    line-height: 1.6;
}

/* ---------- 5. LISTS (a, b, c... and i, ii, iii...) ---------- */
.notes ol,
.notes ul {
    font-size: 12px;
    margin-left: 20px;
}

.notes ol li,
.notes ul li {
    margin-bottom: 4px;
}

/* ---------- 6. COMPENSATION / SALARY TABLE ---------- */
table.items {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
}

table.items th,
table.items td {
    border: 1px solid #000;
    padding: 6px 8px;
    font-size: 12px;
}

table.items th {
    background-color: #f2f2f2;
    font-weight: bold;
}

table.items td.right {
    text-align: right;
}

/* ---------- 7. HEADER TABLE (Private & Confidential box, logo) ---------- */
table.offer-header {
    width: 100%;
    border-collapse: collapse;
}

table.offer-header td {
    border: none;
    font-size: 11px;
}

/* ---------- 8. SIGNATURE / ACKNOWLEDGEMENT TABLE ---------- */
table td b {
    font-size: 12px;
}

/* ---------- 9. PRINT-SPECIFIC ADJUSTMENTS ---------- */
@media print {
    body {
        font-size: 12px;
    }
    h4 {
        page-break-after: avoid;
    }
    .notes {
        page-break-inside: avoid;
    }
}

/* ---------- 10. REPEATING FOOTER (every page) ----------
   wkhtmltopdf repeats "position: fixed" elements on
   every printed page. This is the trick ERPNext/Frappe
   itself uses for print format footers.
   IMPORTANT: Also set a Bottom Margin (e.g. 25mm) in
   Print Format / Print Settings so page content does not
   overlap this footer.
------------------------------------------------------- */
.repeat-footer {
    position: fixed;
    bottom: 0mm;
    left: 0;
    right: 0;
    width: 100%;
    background: #fff;
    padding-top: 4px;
}

.footer-company-name {
    color: #c00000;
    font-weight: bold;
    font-size: 12px;
    margin-bottom: 2px;
}

.footer-text {
    color: #333;
    font-size: 9px;
    line-height: 1.4;
}

/* ---------- 11. PAGE 1 ONLY - BLACK TOP BAR ----------
   This is normal (non-fixed) content, so it only
   appears once, at the very top of page 1.
------------------------------------------------------- */
.page1-topbar {
    width: 100%;
    height: 14px;
    background-color: #000;
    margin-bottom: 10px;
}

