# RM / FG master: any change raises the revision number (see Version history for what changed)
if not doc.is_new() and doc.item_group in ("Raw Material", "Finished Goods"):
    old = doc.get_doc_before_save()
    if old:
        skip = ["modified", "modified_by", "creation", "owner", "name", "idx", "docstatus", "parent", "parentfield", "parenttype", "doctype", "custom_revision_no", "custom_revision_date", "_user_tags", "_comments", "_assign", "_liked_by", "_seen", "__islocal", "__unsaved", "__last_sync_on"]
        n = lambda v: "" if (v is None or v == "" or v == 0) else (str(float(v)) if isinstance(v, (int, float)) else str(v))
        a_doc = old.as_dict()
        b_doc = doc.as_dict()
        changed = False
        for k in set(list(a_doc.keys()) + list(b_doc.keys())):
            if changed or k in skip:
                continue
            a = a_doc.get(k)
            b = b_doc.get(k)
            if isinstance(a, list) or isinstance(b, list):
                a = a or []
                b = b or []
                if len(a) != len(b):
                    changed = True
                    continue
                for i in range(len(b)):
                    ra = a[i]
                    rb = b[i]
                    for kk in set(list(ra.keys()) + list(rb.keys())):
                        if kk not in skip and n(ra.get(kk)) != n(rb.get(kk)):
                            changed = True
            elif n(a) != n(b):
                changed = True
        if changed:
            doc.custom_revision_no = (old.custom_revision_no or 0) + 1
            doc.custom_revision_date = frappe.utils.today()
